package com.campusiq.platform.strategy; import com.campusiq.platform.client.CodeforcesClient; import com.campusiq.platform.dto.PlatformProfileResponse; import com.campusiq.platform.entity.Platform; import org.springframework.stereotype.Component; import java.util.*; @Component public class CodeforcesStrategy implements PlatformProfileStrategy {private final CodeforcesClient c; public CodeforcesStrategy(CodeforcesClient x){c=x;} public Platform getPlatform(){return Platform.CODEFORCES;} public boolean verifyUser(String u){var r=c.info(u);return "OK".equals(r.status())&&r.result()!=null&&!r.result().isEmpty();} public PlatformProfileResponse fetchProfile(String u){var i=c.info(u).result().getFirst();var solved=(int)c.status(u).result().stream().filter(s->"OK".equals(s.verdict())&&s.contestId()!=null&&s.problem()!=null&&s.problem().index()!=null).map(s->s.contestId()+":"+s.problem().index()).distinct().count();String name=String.join(" ",Optional.ofNullable(i.firstName()).orElse(""),Optional.ofNullable(i.lastName()).orElse("")).trim();Double rating=i.rating()==null?null:i.rating().doubleValue();Double max=i.maxRating()==null?null:i.maxRating().doubleValue();return new PlatformProfileResponse(getPlatform(),i.handle(),"https://codeforces.com/profile/"+i.handle(),name.isBlank()?null:name,null,null,i.contribution(),solved,null,null,null,rating,null,null,rating,max,null,null,null,null,null);}}
